import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar'; // or wherever your Navbar is
import Footer from './components/Footer';
import Home from './pages/Home';
import About from './pages/About';
import Services from './pages/Services'; // The new page we added
import Reports from './pages/Reports';

function App() {
  return (
    <Router>
      {/* 1. Navbar stays OUTSIDE Routes so it shows on every page */}
      <Navbar />

      {/* 2. ALL Route elements MUST be inside this Routes wrapper */}
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="/services" element={<Services />} />
        <Route path="/investor-relations" element={<R />} />
      </Routes>

      {/* 3. Footer stays OUTSIDE Routes so it shows on every page */}
      <Footer />
    </Router>
  );
}

export default App;
